==== src/app/heroes/heroes.view-model.ts
import { computed, inject, Injectable, signal } from '@angular/core';
import { heroInitials, STATUS_VARIANT } from '../domain/hero-presentation';
import type { Hero, PowerClass } from '../domain/hero.model';
import { POWER_CLASSES } from '../domain/hero.model';
import { HeroService } from '../domain/hero.service';

/** Sentinel for the class filter's "no restriction" option. */
export const ALL_CLASSES = 'all';

export type ClassFilter = typeof ALL_CLASSES | PowerClass;

/** Component-scoped ViewModel for the Roster screen: the filter bar state and the table rows it yields. */
@Injectable()
export class RosterViewModel {
  private readonly _heroes = inject(HeroService);

  /** Roster count, for the footer. */
  readonly total = this._heroes.count;

  /** The search box text. Matches name, alias and ID, case-insensitively. */
  readonly query = signal('');

  /** The class filter. ALL_CLASSES shows every class. */
  readonly classFilter = signal<ClassFilter>(ALL_CLASSES);

  /** Class filter options, in the order the select shows them. */
  readonly classOptions: readonly ClassFilter[] = [ALL_CLASSES, ...POWER_CLASSES];

  /** Status to badge variant, read by the status column. */
  readonly statusVariant = STATUS_VARIANT;

  /** Heroes that pass both filters, highest power first. Ties keep roster order. */
  readonly rows = computed<readonly Hero[]>(() => {
    const term = this.query().trim().toLowerCase();
    const powerClass = this.classFilter();
    return this._heroes
      .roster()
      .filter((hero) => powerClass === ALL_CLASSES || hero.powerClass === powerClass)
      .filter((hero) => !term || [hero.name, hero.alias, hero.id].some((field) => field.toLowerCase().includes(term)))
      .slice()
      .sort((a, b) => b.powerIndex - a.powerIndex);
  });

  /** How many heroes the table is showing, for the footer. */
  readonly shownCount = computed(() => this.rows().length);

  setQuery(value: string): void {
    this.query.set(value);
  }

  /** The select can emit null when its selection is cleared; that means no class restriction. */
  setClassFilter(value: ClassFilter | null | undefined): void {
    this.classFilter.set(value ?? ALL_CLASSES);
  }

  /** The text a class option shows in the select. */
  optionLabel(option: ClassFilter): string {
    return option === ALL_CLASSES ? 'All classes' : option;
  }

  /** Portrait initials for the hero's avatar. */
  initialsOf(hero: Hero): string {
    return heroInitials(hero.name);
  }
}
==== src/app/heroes/heroes.html
<section class="heroes">
  <header class="heroes__header">
    <h1 hlmH1 id="roster-heading">Roster</h1>
    <p hlmMuted>Every hero on the books. Example data.</p>
  </header>

  <div class="heroes__filters" role="search">
    <hlm-field class="heroes__search">
      <label hlmFieldLabel for="roster-search" class="heroes__sr-only">Search heroes</label>
      <input
        hlmInput
        id="roster-search"
        type="search"
        placeholder="Search name, alias or ID"
        [value]="vm.query()"
        (input)="vm.setQuery(search.value)"
        #search
      />
    </hlm-field>

    <hlm-field class="heroes__class">
      <label hlmFieldLabel for="roster-class" class="heroes__sr-only">Filter by class</label>
      <hlm-select [value]="vm.classFilter()" (valueChange)="vm.setClassFilter($event)">
        <hlm-select-trigger buttonId="roster-class">
          <hlm-select-value />
        </hlm-select-trigger>
        <hlm-select-content *hlmSelectPortal>
          @for (option of vm.classOptions; track option) {
            <hlm-select-item [value]="option">{{ vm.optionLabel(option) }}</hlm-select-item>
          }
        </hlm-select-content>
      </hlm-select>
    </hlm-field>

    <a hlmBtn routerLink="/recruit" class="heroes__recruit">
      <ng-icon hlmIcon name="lucideUserPlus" />
      Recruit
    </a>
  </div>

  <div hlmCard class="heroes__panel" aria-labelledby="roster-heading">
    <div hlmCardContent>
      <div hlmTableContainer>
        <table hlmTable aria-label="Hero roster">
          <thead hlmTHead>
            <tr hlmTr>
              <th hlmTh scope="col">Hero</th>
              <th hlmTh scope="col">Class</th>
              <th hlmTh scope="col" class="heroes__num">Power</th>
              <th hlmTh scope="col">Status</th>
              <th hlmTh scope="col">Clearance</th>
              <th hlmTh scope="col">
                <span class="heroes__sr-only">Actions</span>
              </th>
            </tr>
          </thead>
          <tbody hlmTBody>
            @for (hero of vm.rows(); track hero.id) {
              <tr hlmTr>
                <td hlmTd>
                  <div class="heroes__hero">
                    <hlm-avatar>
                      <span hlmAvatarFallback>{{ vm.initialsOf(hero) }}</span>
                    </hlm-avatar>
                    <div class="heroes__identity">
                      <span hlmSmall>{{ hero.name }}</span>
                      <span hlmMuted>{{ hero.id }}</span>
                    </div>
                  </div>
                </td>
                <td hlmTd>
                  <span hlmBadge variant="outline">{{ hero.powerClass }}</span>
                </td>
                <td hlmTd class="heroes__num">{{ hero.powerIndex }}</td>
                <td hlmTd>
                  <span hlmBadge [variant]="vm.statusVariant[hero.status]">{{ hero.status }}</span>
                </td>
                <td hlmTd>{{ hero.clearanceTier }}</td>
                <td hlmTd>
                  <a
                    hlmBtn
                    variant="ghost"
                    size="icon"
                    [routerLink]="['/detail', hero.id]"
                    [attr.aria-label]="'Edit ' + hero.name"
                    [hlmTooltip]="'Edit ' + hero.name"
                  >
                    <ng-icon hlmIcon name="lucidePencil" />
                  </a>
                </td>
              </tr>
            } @empty {
              <tr hlmTr>
                <td hlmTd colspan="6">No heroes match these filters.</td>
              </tr>
            }
          </tbody>
        </table>
      </div>
    </div>
    <footer hlmCardFooter class="heroes__footer">
      <span hlmSmall>{{ vm.shownCount() }} of {{ vm.total() }} heroes</span>
      <span hlmMuted>Sorted by power</span>
    </footer>
  </div>
</section>

