@reference "../../styles.css";

.hero-detail { @apply grid content-start gap-6 p-6; }
.hero-detail__back { @apply justify-self-start; }

.hero-detail__header { @apply grid gap-4 md:grid-cols-[1fr_auto] md:items-start; }
.hero-detail__identity { @apply flex min-w-0 items-center gap-4; }
.hero-detail__names { @apply grid min-w-0 gap-1; }
.hero-detail__badges { @apply flex flex-wrap gap-2; }
.hero-detail__actions { @apply flex flex-wrap gap-2; }

.hero-detail__tabs { @apply grid min-w-0 gap-4; }
.hero-detail__tab-list { @apply max-w-full overflow-x-auto; }
.hero-detail__panel { @apply grid min-w-0 content-start gap-4; }

.hero-detail__two-col { @apply grid gap-4 md:grid-cols-2; }
.hero-detail__stats { @apply grid gap-4 sm:grid-cols-3; }
.hero-detail__dossier { @apply grid gap-4; }
.hero-detail__fact { @apply grid gap-1; }

.hero-detail__form { @apply grid max-w-2xl gap-4; }
.hero-detail__fields { @apply grid gap-4 md:grid-cols-2; }
.hero-detail__notes { @apply md:col-span-2; }
.hero-detail__form-actions { @apply flex flex-wrap justify-end gap-2; }

.hero-detail__missing { @apply grid gap-2; }

