input.command:
node -e '
const fs=require("fs");
const v="src/app/hero-detail/hero-detail.view-model.ts";
let s=fs.readFileSync(v,"utf8");
s=s.replace("import { formMeta } from \x27../forms/zod-meta\x27;","import type { FormFieldMeta } from \x27../forms/form-field-meta\x27;\nimport { formMeta } from \x27../forms/zod-meta\x27;");
s=s.replace("readonly fields = formMeta(heroEditSchema);","readonly fields = formMeta(heroEditSchema) as Record<keyof HeroModel, FormFieldMeta>;");
fs.writeFileSync(v,s);
const h="src/app/hero-detail/hero-detail.html";
let t=fs.readFileSync(h,"utf8");
t=t.replace(`type="number" min="0" max="100" [formField]`,`type="number" [formField]`);
fs.writeFileSync(h,t);
' && grep -n "fields =" src/app/hero-detail/hero-detail.view-model.ts && npx ng build 2>&1 | sed 's/\x1b\[[0-9;]*m//g' | grep -v "^\s*$" | tail -60

